/**
 * Coverage for the bulk run accessors {@code NativeAdjacency.copyRun} / {@code copyContexts} (plan:
 * plans/lmdb-native-engine/23-kernel-capability-parity.md, M1). Vectorized kernels read whole runs through these, so a
 * block-copying override must agree element-for-element with the per-index accessors it replaces. Both the interface
 * default (looping {@code neighborAt}) and the CSR override (a {@code System.arraycopy}) are checked.
 */
public class LmdbCsrAdjacencyBulkCopyTest {

	private static final String EX = "http://example.com/";
	private static final String ENABLED_FLAG = "rdf4j.lmdb.csrCache.enabled";
	private static final String MIN_PROBES_FLAG = "rdf4j.lmdb.csrCache.minProbes";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private Map<String, String> previousProperties;

	@BeforeEach
	public void setUp() {
		previousProperties = new HashMap<>();
		for (String property : new String[] { ENABLED_FLAG, MIN_PROBES_FLAG }) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty(ENABLED_FLAG, "true");
		System.setProperty(MIN_PROBES_FLAG, "1");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p1 = vf.createIRI(EX, "p1");
			IRI p2 = vf.createIRI(EX, "p2");
			connection.begin();
			for (int i = 0; i < 120; i++) {
				IRI subject = vf.createIRI(EX, "s" + i);
				IRI middle = vf.createIRI(EX, "m" + i);
				connection.add(subject, p1, middle);
				// Uneven run lengths so the copies exercise more than one fixed width.
				for (int branch = 0; branch <= i % 4; branch++) {
					connection.add(middle, p2, vf.createIRI(EX, "v" + i + "-" + branch));
				}
			}
			connection.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
			if (entry.getValue() == null) {
				System.clearProperty(entry.getKey());
			} else {
				System.setProperty(entry.getKey(), entry.getValue());
			}
		}
	}

	@Test
	public void csrBlockCopyAgreesWithPerIndexAccessors() throws Exception {
		LmdbStore sail = (LmdbStore) repository.getSail();
		ValueFactory vf = repository.getValueFactory();
		IRI p1 = vf.createIRI(EX, "p1");
		IRI p2 = vf.createIRI(EX, "p2");
		CsrProbeWarmupAccess.warmBySubject(sail, p1, p2);

		LmdbSailStore backingStore = sail.getBackingStore();
		try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.NONE)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long p2Id = source.idOf(p2);
			try (NativeLmdbQuerySource.NativeProbe probe = source.newProbe()) {
				NativeLmdbQuerySource.NativeAdjacency view = probe.adjacency(p2Id, true);
				assertNotNull(view, "warm-up must have built a subject-keyed CSR view for p2");
				int keys = view.keyCount();
				assertTrue(keys > 0, "expected an enumerable key domain, got keyCount=" + keys);

				int copiedRuns = 0;
				for (int dense = 0; dense < keys; dense++) {
					copiedRuns += assertRunCopiesMatch(view, dense);
				}
				assertTrue(copiedRuns > 0, "expected at least one non-empty run");
			}
		}
	}

	@Test
	public void interfaceDefaultCopiesMatchPerIndexAccessors() {
		// A view that does NOT override the bulk methods, so the interface default loop is what runs.
		long[] neighbors = { 7L, -1L, 0L, 900L, 3L };
		long[] contexts = { 0L, 5L, -1L, 0L, 42L };
		NativeLmdbQuerySource.NativeAdjacency view = new NativeLmdbQuerySource.NativeAdjacency() {
			@Override
			public int denseIdOf(long key) {
				return key == 1L ? 0 : -1;
			}

			@Override
			public int runStart(int dense) {
				return 0;
			}

			@Override
			public int runEnd(int dense) {
				return neighbors.length;
			}

			@Override
			public long neighborAt(int index) {
				return neighbors[index];
			}

			@Override
			public long contextAt(int index) {
				return contexts[index];
			}

			@Override
			public int keyCount() {
				return 1;
			}

			@Override
			public long keyAt(int dense) {
				return 1L;
			}
		};
		assertEquals(neighbors.length, assertRunCopiesMatch(view, 0));
	}

	/**
	 * Asserts that both bulk copies reproduce the per-index accessors for one run, including a sub-range copy and a
	 * copy into the middle of a larger buffer, and returns the run length.
	 */
	private static int assertRunCopiesMatch(NativeLmdbQuerySource.NativeAdjacency view, int dense) {
		int start = view.runStart(dense);
		int end = view.runEnd(dense);
		int length = end - start;
		if (length == 0) {
			return 0;
		}

		long[] neighbors = new long[length];
		view.copyRun(start, end, neighbors, 0);
		long[] contexts = new long[length];
		view.copyContexts(start, end, contexts, 0);
		for (int i = 0; i < length; i++) {
			assertEquals(view.neighborAt(start + i), neighbors[i], "neighbor at run offset " + i);
			assertEquals(view.contextAt(start + i), contexts[i], "context at run offset " + i);
		}

		// Copying into the middle of a wider buffer must not disturb the surrounding positions.
		int offset = 3;
		long[] padded = new long[length + offset + 2];
		Arrays.fill(padded, Long.MIN_VALUE);
		view.copyRun(start, end, padded, offset);
		for (int i = 0; i < offset; i++) {
			assertEquals(Long.MIN_VALUE, padded[i], "prefix position " + i + " must be untouched");
		}
		for (int i = 0; i < length; i++) {
			assertEquals(view.neighborAt(start + i), padded[offset + i], "offset neighbor at " + i);
		}
		for (int i = offset + length; i < padded.length; i++) {
			assertEquals(Long.MIN_VALUE, padded[i], "suffix position " + i + " must be untouched");
		}

		// A strict sub-range must copy exactly that slice.
		if (length > 1) {
			long[] tail = new long[length - 1];
			view.copyRun(start + 1, end, tail, 0);
			for (int i = 0; i < tail.length; i++) {
				assertEquals(view.neighborAt(start + 1 + i), tail[i], "sub-range neighbor at " + i);
			}
		}
		return length;
	}
}
